import React, { ComponentType } from 'react';
import styled from 'styled-components';

import {
  ArrowSmallDownRightIcon,
  ArrowSmallRightIcon,
  ArrowSmallUpRightIcon,
} from '@dynatrace/strato-icons';

import { TREND_FONT_SIZE } from '../../../constants.js';
import { TrendDirection } from '../types/trend-direction.js';

const StyledIcon = /* @__PURE__ */ styled('div')<{ color: string }>(
  ({ color }) => ({
    color,
    position: 'relative',
    fontSize: `calc(${TREND_FONT_SIZE} * 1px)`,

    '& svg': {
      position: 'absolute',
      width: '2ch',
      height: '2ch',
      top: '50%',
      transform: 'translateY(-50%)',
    },
  }),
);

interface TrendIconProps {
  direction: TrendDirection;
  color: string;
}

export const Icon = ({ direction, color }: TrendIconProps) => {
  const iconMap: Record<TrendDirection, ComponentType> = {
    upward: ArrowSmallUpRightIcon,
    downward: ArrowSmallDownRightIcon,
    neutral: ArrowSmallRightIcon,
  };

  const Icon = iconMap[direction] ?? ArrowSmallRightIcon;

  return (
    <StyledIcon color={color}>
      <Icon />
    </StyledIcon>
  );
};
